'use client';

import { useState, type FormEvent } from 'react';
import { Send, CheckCircle, AlertCircle } from 'lucide-react';
import { submitContactForm } from '@/lib/api';

interface FormState {
  name: string;
  email: string;
  subject: string;
  message: string;
}

const INITIAL: FormState = { name: '', email: '', subject: '', message: '' };
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(form: FormState): Partial<FormState> {
  const errors: Partial<FormState> = {};
  if (!form.name.trim() || form.name.trim().length < 2) errors.name = 'Name must be at least 2 characters.';
  if (!form.email.trim() || !EMAIL_RE.test(form.email)) errors.email = 'A valid email address is required.';
  if (!form.subject.trim() || form.subject.trim().length < 3) errors.subject = 'Subject must be at least 3 characters.';
  if (!form.message.trim() || form.message.trim().length < 10) errors.message = 'Message must be at least 10 characters.';
  return errors;
}

export default function Contact() {
  const [form, setForm] = useState<FormState>(INITIAL);
  const [errors, setErrors] = useState<Partial<FormState>>({});
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [serverError, setServerError] = useState('');

  function handleChange(e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
    if (errors[name as keyof FormState]) {
      setErrors((prev) => ({ ...prev, [name]: undefined }));
    }
  }

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    const validationErrors = validate(form);
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }
    setStatus('loading');
    setServerError('');
    try {
      await submitContactForm(form);
      setStatus('success');
      setForm(INITIAL);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Something went wrong. Please try again.';
      setServerError(message);
      setStatus('error');
    }
  }

  const inputBase =
    'w-full px-4 py-2.5 rounded-lg bg-slate-900 border text-sm text-slate-100 placeholder-slate-600 focus:outline-none focus:ring-2 focus:ring-purple-500/50 transition-colors';

  return (
    <section
      id="contact"
      className="py-20 px-4 sm:px-6 lg:px-8 border-t border-slate-900"
      aria-label="Contact section"
    >
      <div className="max-w-2xl mx-auto">
        <div className="mb-12 text-center">
          <h2 className="text-3xl font-bold text-slate-100 mb-4">Get In Touch</h2>
          <div className="w-12 h-1 bg-gradient-to-r from-purple-500 to-cyan-500 rounded-full mb-6 mx-auto" aria-hidden="true" />
          <p className="text-slate-400 text-sm">
            Have a project in mind or want to connect? Send a message and I'll get back to you.
          </p>
        </div>

        {status === 'success' ? (
          <div
            role="alert"
            className="flex flex-col items-center justify-center text-center gap-4 py-16 bg-slate-900 border border-green-500/20 rounded-xl"
          >
            <CheckCircle size={40} className="text-green-400" aria-hidden="true" />
            <div>
              <p className="text-slate-100 font-semibold mb-1">Message sent!</p>
              <p className="text-slate-400 text-sm">Thanks for reaching out. I'll respond as soon as I can.</p>
            </div>
            <button
              onClick={() => setStatus('idle')}
              className="mt-2 text-sm text-purple-400 hover:text-purple-300 underline underline-offset-4 transition-colors"
            >
              Send another message
            </button>
          </div>
        ) : (
          <form
            onSubmit={handleSubmit}
            noValidate
            className="bg-slate-900 border border-slate-800 rounded-xl p-6 sm:p-8 space-y-5"
            aria-label="Contact form"
          >
            {/* Name */}
            <div>
              <label htmlFor="name" className="block text-sm font-medium text-slate-300 mb-1.5">
                Name <span className="text-red-400" aria-hidden="true">*</span>
              </label>
              <input
                id="name"
                name="name"
                type="text"
                value={form.name}
                onChange={handleChange}
                placeholder="Your name"
                autoComplete="name"
                aria-required="true"
                aria-invalid={!!errors.name}
                aria-describedby={errors.name ? 'name-error' : undefined}
                className={`${inputBase} ${errors.name ? 'border-red-500/60' : 'border-slate-800 hover:border-slate-700'}`}
              />
              {errors.name && (
                <p id="name-error" role="alert" className="mt-1 text-xs text-red-400">{errors.name}</p>
              )}
            </div>

            {/* Email */}
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-slate-300 mb-1.5">
                Email <span className="text-red-400" aria-hidden="true">*</span>
              </label>
              <input
                id="email"
                name="email"
                type="email"
                value={form.email}
                onChange={handleChange}
                placeholder="you@example.com"
                autoComplete="email"
                aria-required="true"
                aria-invalid={!!errors.email}
                aria-describedby={errors.email ? 'email-error' : undefined}
                className={`${inputBase} ${errors.email ? 'border-red-500/60' : 'border-slate-800 hover:border-slate-700'}`}
              />
              {errors.email && (
                <p id="email-error" role="alert" className="mt-1 text-xs text-red-400">{errors.email}</p>
              )}
            </div>

            {/* Subject */}
            <div>
              <label htmlFor="subject" className="block text-sm font-medium text-slate-300 mb-1.5">
                Subject <span className="text-red-400" aria-hidden="true">*</span>
              </label>
              <input
                id="subject"
                name="subject"
                type="text"
                value={form.subject}
                onChange={handleChange}
                placeholder="What's this about?"
                aria-required="true"
                aria-invalid={!!errors.subject}
                aria-describedby={errors.subject ? 'subject-error' : undefined}
                className={`${inputBase} ${errors.subject ? 'border-red-500/60' : 'border-slate-800 hover:border-slate-700'}`}
              />
              {errors.subject && (
                <p id="subject-error" role="alert" className="mt-1 text-xs text-red-400">{errors.subject}</p>
              )}
            </div>

            {/* Message */}
            <div>
              <label htmlFor="message" className="block text-sm font-medium text-slate-300 mb-1.5">
                Message <span className="text-red-400" aria-hidden="true">*</span>
              </label>
              <textarea
                id="message"
                name="message"
                rows={5}
                value={form.message}
                onChange={handleChange}
                placeholder="Your message..."
                aria-required="true"
                aria-invalid={!!errors.message}
                aria-describedby={errors.message ? 'message-error' : undefined}
                className={`${inputBase} resize-none ${errors.message ? 'border-red-500/60' : 'border-slate-800 hover:border-slate-700'}`}
              />
              {errors.message && (
                <p id="message-error" role="alert" className="mt-1 text-xs text-red-400">{errors.message}</p>
              )}
            </div>

            {/* Server error */}
            {status === 'error' && serverError && (
              <div role="alert" className="flex items-start gap-2 p-3 rounded-lg bg-red-500/10 border border-red-500/20">
                <AlertCircle size={16} className="text-red-400 mt-0.5 shrink-0" aria-hidden="true" />
                <p className="text-sm text-red-400">{serverError}</p>
              </div>
            )}

            {/* Submit */}
            <button
              type="submit"
              disabled={status === 'loading'}
              className="w-full flex items-center justify-center gap-2 px-6 py-3 rounded-xl bg-purple-600 hover:bg-purple-500 disabled:opacity-60 disabled:cursor-not-allowed text-white font-medium text-sm transition-colors"
            >
              {status === 'loading' ? (
                <>
                  <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" aria-hidden="true" />
                  Sending…
                </>
              ) : (
                <>
                  <Send size={15} aria-hidden="true" />
                  Send Message
                </>
              )}
            </button>
          </form>
        )}
      </div>
    </section>
  );
}
